def case(id,gid,role,mat,taskde,tasken,solde,solen,rubric):
 cases.append({'caseId':id,'goalId':gid,'caseRole':role,'evidenceLevel':'E0','maximumClaimScope':'G0','material':mat,'taskDe':taskde,'taskEn':tasken,'workedSolutionDe':solde,'workedSolutionEn':solen,'rubric':[{'criterionDe':de,'criterionEn':en,'points':1} for de,en in rubric],'totalPoints':len(rubric),'actualPracticalExecutionRequired':False,'learnerEvidenceObserved':False})
